// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    function setUp() public { c = new MultiplicatorX3(); }
    function testFuzz_property(uint256 amount, address nonOwner) public {
        vm.assume(amount > 0);
        vm.assume(nonOwner != address(0) && nonOwner != address(c) && nonOwner != address(this));
        vm.deal(address(c), amount);
        uint256 balBefore = address(c).balance;
        vm.prank(nonOwner);
        bool reverted = false;
        try c.withdraw() { } catch { reverted = true; }
        if (reverted) {
            assertEq(address(c).balance, balBefore);
        } else {
            assertTrue(false);
        }
    }
}
